draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;
ctx.textAlign = "center";

var tableY = H * 0.42;
var edgeX = W * 0.62;
var bw = W * 0.16, bh = H * 0.15;
var bx = W * 0.26, by = tableY - bh;

// table
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(W * 0.05, tableY);
ctx.lineTo(edgeX, tableY);
ctx.lineTo(edgeX, H * 0.72);
ctx.stroke();

// block A on the table
ctx.fillStyle = C.figure;
ctx.globalAlpha = 0.25;
ctx.fillRect(bx, by, bw, bh);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.ink;
ctx.strokeRect(bx, by, bw, bh);
ctx.fillStyle = C.ink;
ctx.fillText("M on table", bx + bw / 2, by - 6);

var acx = bx + bw / 2, acy = by + bh / 2;

function arrow(x1, y1, x2, y2, col) {
  ctx.strokeStyle = col;
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  var ang = Math.atan2(y2 - y1, x2 - x1);
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - 8 * Math.cos(ang - 0.4), y2 - 8 * Math.sin(ang - 0.4));
  ctx.lineTo(x2 - 8 * Math.cos(ang + 0.4), y2 - 8 * Math.sin(ang + 0.4));
  ctx.closePath();
  ctx.fill();
}

var L = H * 0.20;
arrow(acx, acy, acx, acy - L, C.figure);
arrow(acx, acy, acx, acy + L, C.figure);
arrow(acx, acy, acx + bw * 0.95, acy, C.accent);
ctx.fillStyle = C.figure;
ctx.textAlign = "right";
ctx.fillText("N", acx - 6, acy - L + 4);
ctx.fillText("Mg", acx - 6, acy + L);
ctx.textAlign = "left";
ctx.fillStyle = C.accent;
ctx.fillText("T", acx + bw * 0.95 + 5, acy + 4);

// rope over the pulley
var R = Math.min(W, H) * 0.05;
var pcx = edgeX, pcy = tableY - R;
ctx.strokeStyle = C.accent;
ctx.beginPath();
ctx.moveTo(bx + bw, tableY - R * 2);
ctx.lineTo(pcx, tableY - R * 2);
ctx.stroke();
ctx.beginPath();
ctx.arc(pcx, pcy, R, -Math.PI / 2, 0);
ctx.stroke();

var hy = H * 0.60;
ctx.beginPath();
ctx.moveTo(pcx + R, pcy);
ctx.lineTo(pcx + R, hy);
ctx.stroke();

ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.arc(pcx, pcy, R, 0, Math.PI * 2);
ctx.stroke();

// hanging block
var hw = W * 0.13, hh = H * 0.14;
var hx = pcx + R - hw / 2;
ctx.fillStyle = C.figure;
ctx.globalAlpha = 0.25;
ctx.fillRect(hx, hy, hw, hh);
ctx.globalAlpha = 1;
ctx.strokeStyle = C.ink;
ctx.strokeRect(hx, hy, hw, hh);

var hcx = hx + hw / 2, hcy = hy + hh / 2;
var L2 = H * 0.17;
arrow(hcx, hcy, hcx, hcy - L2, C.accent);
arrow(hcx, hcy, hcx, hcy + L2, C.figure);
ctx.fillStyle = C.accent;
ctx.textAlign = "left";
ctx.fillText("T", hcx + 6, hcy - L2 + 6);
ctx.fillStyle = C.figure;
ctx.fillText("mg", hcx + 6, hcy + L2);
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("m hanging", hcx, hy - 6);

// constraint note
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("same rope, so the same T at both ends", W * 0.05, H * 0.92);
ctx.fillText("same rope length, so the same |a|", W * 0.05, H * 0.98);
